    let h00_derivative = 6.0 * t * t - 6.0 * t;
    let h10_derivative = 3.0 * t * t - 4.0 * t + 1.0;
    let h01_derivative = -6.0 * t * t + 6.0 * t;
    let h11_derivative = 3.0 * t * t - 2.0 * t;

